package com.wanderly.config; import com.wanderly.model.*; import com.wanderly.repository.TripRepository; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import java.time.LocalDate;
@Configuration public class SeedData { @Bean CommandLineRunner seed(TripRepository r){return args->{if(r.count()==0){Trip a=new Trip();a.setTitle("A little escape");a.setDestination("Udaipur, India");a.setStartDate(LocalDate.now().plusDays(18));a.setEndDate(LocalDate.now().plusDays(22));a.setTravellers(2);a.setStatus(TripStatus.PLANNED);a.setNotes("Lakeside mornings, old-city walks and slow sunsets.");a.setImageUrl("https://images.unsplash.com/photo-1599661046827-dacff0c0f09a?auto=format&fit=crop&w=900&q=85");r.save(a);Trip b=new Trip();b.setTitle("Coastal daydream");b.setDestination("Goa, India");b.setStartDate(LocalDate.now().plusDays(4));b.setEndDate(LocalDate.now().plusDays(7));b.setTravellers(3);b.setStatus(TripStatus.IN_PROGRESS);b.setNotes("Beach cafés, local food and a little adventure.");b.setImageUrl("https://images.unsplash.com/photo-1512343879784-a960bf40e7f2?auto=format&fit=crop&w=900&q=85");r.save(b);}};}}
